def encode(message):
    def swap_case(char):
        if char.islower():
            return char.upper()
        elif char.isupper():
            return char.lower()
        return char

    def replace_vowels(char, previous_char):
        vowels = {'a': 'd', 'e': 'q', 'i': 'l', 'o': 'c', 'u': 's'}
        vowels['A': 'D', 'E': 'Q', 'I': 'L', 'O': 'C', 'U': 'S']
        if char in vowels and previous_char in vowels:
            new_char = vowels[char]
            return new_char
        return char

    def swap_vowels(message):
        vowels = 'aeiouAEIOU'
        pattern = r'[aeiouAEIOU]'
        message = re.sub(pattern, lambda match: vowels[(vowels.index(match.group(0)) + 2) % len(vowels)], message)
        return message

    def encode_vowels(message):
        encoded_message = []
        for char in message:
            if char in 'aeiouAEIOU':
                encoded_message.append(replace_vowels(char, encoded_message[-2]))
            else:
                encoded_message.append(swap_case(char))
        return ''.join(encoded_message)

    encoded_message = encode_vowels(message)
    return encoded_message
