def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_digits(num):
        """Helper function to calculate the sum of digits of a number."""
        if num < 0:
            # Calculate the sum of the first digit and the absolute value of the rest
            return -1 * sum(-1 * int(digit) for digit in str(num))
        else:
            # Calculate the sum of all digits of the positive number
            return sum(int(digit) for digit in str(num))

    return sum(sum_of_digits(num) > 0 for num in arr)
