from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[[float('inf')] * (k + 1) for _ in range(n)] for _ in range(n)]
    min_list = [[[None] * (k + 1) for _ in range(n)] for _ in range(n)]

    def dfs(x, y, steps):
        if dp[x][y][steps] != float('inf'):
            return min_list[x][y][steps]

        if steps == 1:
            return grid[x][y]

        min_val = float('inf')
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                val = dfs(nx, ny, steps - 1)
                if val < min_val:
                    min_val = val
                    min_list[x][y][steps] = min_list[x][y][steps - 1] = (x, y, val)

        return min_val

    min_val = float('inf')
    for x in range(n):
        for y in range(n):
            dfs(x, y, k)
            min_val = min(min_val, dfs(x, y, k))

    if min_val == float('inf'):
        return []

    path = []
    while k > 0:
        x, y, val = min_list[x][y][k - 1]
        path.append(val)
        k -= 1
    path.reverse()
    return path
