def fix_spaces(text):
    result = []
    current_char = ''

    for char in text:
        if char == ' ' and len(result) > 2:
            result.append('-')
        elif char == ' ':
            result.append('_')
        else:
            result.append(char)
            current_char = char

        if current_char != '_' and current_char != '-':
            if len(result) > 2 and result[-1] == ' ' and result[-2] == ' ':
                result[-1] = '-'

    return ''.join(result)

